import boto3
from botocore.exceptions import ClientError

processed = boto3.resource("dynamodb").Table("processed_events")

def lambda_handler(event, context):
    event_id = event["id"]
    try:
        # Fails if this id was already saved -> we skip the duplicate
        processed.put_item(Item={"id": event_id},
                           ConditionExpression="attribute_not_exists(id)")
    except ClientError as e:
        if e.response["Error"]["Code"] == "ConditionalCheckFailedException":
            return {"status": "duplicate, skipped"}
        raise
    charge_customer(event)      # runs only once per event id
    return {"status": "done"}

import json

def lambda_handler(event, context):
    failures = []
    for record in event["Records"]:
        try:
            order = json.loads(record["body"])
            process_order(order)
        except Exception as e:
            print("Failed:", record["messageId"], e)
            failures.append({"itemIdentifier": record["messageId"]})

    # Only failed messages go back to the queue
    return {"batchItemFailures": failures}

import json

def lambda_handler(event, context):
    body = json.loads(event.get("body") or "{}")
    params = event.get("queryStringParameters") or {}

    if "name" not in body:
        return {"statusCode": 400,
                "headers": {"Content-Type": "application/json"},
                "body": json.dumps({"error": "name is required"})}

    return {
        "statusCode": 201,
        "headers": {"Content-Type": "application/json",
                    "Access-Control-Allow-Origin": "*"},
        "body": json.dumps({"created": body["name"], "source": params.get("source")}),
    }

