from aws_lambda_powertools import Logger, Tracer

logger = Logger(service="orders")
tracer = Tracer(service="orders")

@logger.inject_lambda_context          # adds request id, cold start, etc.
@tracer.capture_lambda_handler         # X-Ray tracing
def lambda_handler(event, context):
    logger.info("Order received", extra={"order_id": event.get("order_id")})
    return {"ok": True}

